import {useEffect,useLayoutEffect,useMemo,useRef,useState} from 'react'
import {Archive,CalendarDays,Check,ChevronDown,ChevronLeft,ChevronRight,Circle,Clock3,Command,FileText,FileUp,FolderOpen,History,Inbox,LayoutList,Mail,Menu,Moon,MoreHorizontal,Pencil,Plus,RefreshCw,Search,Settings,ShieldCheck,Sun,Trash2,TriangleAlert,X} from 'lucide-react'
import {api} from './lib/api'
import type {ActorAnalysis,ImportBatch,Item,List,ParsedItem,ParsedPlan,Plan,SchedulePreview,View} from './types'
import './settings.css'

const isoToday=()=>new Date().toLocaleDateString('en-CA')
const shiftDate=(value:string,days:number)=>{const date=new Date(`${value}T12:00:00`);date.setDate(date.getDate()+days);return date.toLocaleDateString('en-CA')}
const prettyDate=(s?:string|null)=>s?new Intl.DateTimeFormat('zh-CN',{month:'short',day:'numeric',weekday:'short'}).format(new Date(`${s}T12:00:00`)):''
const formatMinutes=(value:number)=>{const minutes=Math.max(0,Math.round(value)),hours=Math.floor(minutes/60),rest=minutes%60;return hours?`${hours} 小时${rest?` ${rest} 分钟`:''}`:`${rest} 分钟`}
const colors=['#70757d','#e05a47','#da8b24','#2f9e61','#3984d8','#8a68d4']
type ImportResult={plan_id:number;created:number;skipped:number;list_ids:number[];item_ids:number[]}
type UploadProgress={phase:'scanning'|'uploading'|'extracting';fileName:string;processedBytes:number;totalBytes:number;transferredBytes:number;transferBytes:number;filesDone:number;totalFiles:number;startedAt:number}

const mediaExtensions=new Set(['.mp4','.mkv','.mov','.webm','.m4v','.mp3','.m4a','.wav','.flac','.aac','.ogg'])
const fileExtension=(name:string)=>{const index=name.lastIndexOf('.');return index>=0?name.slice(index).toLowerCase():''}
const relativeFilePath=(file:File)=>((file as File&{webkitRelativePath?:string}).webkitRelativePath||file.name).replaceAll('\\','/')
const formatBytes=(value:number)=>{const units=['B','KB','MB','GB','TB'];let size=Math.max(0,value),index=0;while(size>=1024&&index<units.length-1){size/=1024;index++}return `${size.toFixed(index>1?1:0)} ${units[index]}`}
const readMediaDuration=(file:File)=>new Promise<number|null>(resolve=>{const media=document.createElement(file.type.startsWith('audio/')?'audio':'video'),url=URL.createObjectURL(file);let settled=false;const finish=(value:number|null)=>{if(settled)return;settled=true;clearTimeout(timer);media.removeAttribute('src');media.load();URL.revokeObjectURL(url);resolve(value)};const timer=window.setTimeout(()=>finish(null),15000);media.preload='metadata';media.onloadedmetadata=()=>finish(Number.isFinite(media.duration)&&media.duration>0?Math.round(media.duration):null);media.onerror=()=>finish(null);media.src=url})
const loadAllItems=async()=>{const pageSize=1000,result:Item[]=[];for(let offset=0;;offset+=pageSize){const page=await api.get<Item[]>(`/api/items?limit=${pageSize}&offset=${offset}`);result.push(...page);if(page.length<pageSize)return result}}

function App(){
 const [lists,setLists]=useState<List[]>([]),[items,setItems]=useState<Item[]>([]),[plans,setPlans]=useState<Plan[]>([])
 const [view,setView]=useState<View>('today'),[search,setSearch]=useState(''),[loading,setLoading]=useState(true),[sidebar,setSidebar]=useState(false)
 const [editor,setEditor]=useState<Partial<Item>|null>(null),[theme,setTheme]=useState(localStorage.theme||'system'),[toast,setToast]=useState<{id:number;message:string;kind:'success'|'error'}|null>(null)
 const [deleteTarget,setDeleteTarget]=useState<List|null>(null),[deleting,setDeleting]=useState(false)
 const notify=(message:string,kind:'success'|'error'='success')=>{const id=Date.now();setToast({id,message,kind});window.setTimeout(()=>setToast(current=>current?.id===id?null:current),2800)}
 const load=async()=>{try{const [ls,it,ps]=await Promise.all([api.get<List[]>('/api/lists'),loadAllItems(),api.get<Plan[]>('/api/plans')]);setLists(ls);setItems(it);setPlans(ps)}finally{setLoading(false)}}
 useEffect(()=>{load()},[])
 useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.theme=theme},[theme])
 const currentList=view.startsWith('list-')?lists.find(x=>x.id===Number(view.slice(5))):undefined
 const title=currentList?.name||({inbox:'Inbox',today:'今天',upcoming:'即将到来',all:'全部项目',history:'历史',import:'导入内容',settings:'设置'} as Record<string,string>)[view]
 const visible=useMemo(()=>items.filter(i=>{if(search&&!`${i.title} ${i.description||''} ${i.notes||''} ${i.tags.join(' ')}`.toLowerCase().includes(search.toLowerCase()))return false;if(currentList)return i.list_id===currentList.id;if(view==='inbox')return i.list_id===lists.find(l=>l.name==='Inbox')?.id;if(view==='today')return i.due_date===isoToday();if(view==='upcoming')return !!i.due_date&&i.due_date>isoToday();if(view==='all')return true;return false}),[items,view,currentList,search,lists])
 const toggle=async(i:Item)=>{try{await api.post<Item>(`/api/items/${i.id}/complete`);await load()}catch(e){notify(`更新完成状态失败：${String(e)}`,'error')}}
 const removeItem=async(id:number)=>{await api.delete(`/api/items/${id}`);setItems(x=>x.filter(i=>i.id!==id));notify('项目已删除');load()}
 const quickAdd=async(title:string)=>{if(!title.trim())return;const listId=currentList?.id||lists.find(l=>l.name==='Inbox')?.id;await api.post('/api/items',{title:title.trim(),list_id:listId??null,due_date:view==='today'?isoToday():null,tags:[],metadata:{}});notify('项目已添加');load()}
 const addList=async()=>{const name=prompt('新清单名称');if(!name?.trim())return;const created=await api.post<List>('/api/lists',{name:name.trim(),color:colors[(lists.length+1)%colors.length],metadata:{}});await load();setView(`list-${created.id}`);notify(`已创建清单“${created.name}”`)}
 const renameList=async()=>{if(!currentList)return;const name=prompt('清单新名称',currentList.name);if(!name?.trim()||name.trim()===currentList.name)return;await api.put(`/api/lists/${currentList.id}`,{name:name.trim()});await load();notify('清单名称已更新')}
 const deleteList=async()=>{if(!deleteTarget||deleteTarget.name==='Inbox')return;setDeleting(true);try{await api.delete(`/api/lists/${deleteTarget.id}`);setDeleteTarget(null);setView('today');notify(`清单“${deleteTarget.name}”已删除`);await load()}catch(e){notify(`删除失败：${String(e)}`,'error')}finally{setDeleting(false)}}
 return <div className="shell">
  <Sidebar open={sidebar} close={()=>setSidebar(false)} view={view} setView={v=>{setView(v);setSidebar(false)}} lists={lists} addList={addList}/>
  <main className="main">
   <header className="topbar"><button className="icon mobile" onClick={()=>setSidebar(true)}><Menu/></button><div className="search"><Search/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="搜索项目、备注或标签"/><kbd>⌘ K</kbd></div><button className="icon" title="快速添加" onClick={()=>setEditor({list_id:currentList?.id||lists.find(l=>l.name==='Inbox')?.id,due_date:view==='today'?isoToday():null})}><Plus/></button></header>
   <section className="content"><div className="view-panel" key={view}>
     {view==='import'?<ImportPage onDone={async result=>{setView(result.created>0&&result.list_ids[0]?`list-${result.list_ids[0]}`:'all');try{await load();if(result.created>0)notify(`已导入 ${result.created} 个任务${result.skipped?`，跳过 ${result.skipped} 个重复项`:''}`);else notify(result.skipped?`没有创建新任务：${result.skipped} 个项目均为重复项`:'没有可导入的任务','error')}catch{notify('任务已经写入，但列表刷新失败；请重新启动应用查看','error')}}}/>:view==='settings'?<SettingsPage theme={theme} setTheme={setTheme} notify={notify} onTasksChanged={load}/>:view==='history'?<HistoryPage plans={plans}/>:<>
     <div className="page-title"><div><p className="eyebrow">{currentList?'清单':view==='today'?prettyDate(isoToday()):'CHECKLIST HUB'}</p><h1>{title}</h1><p>{visible.filter(i=>!i.completed).length} 项待完成 · {visible.filter(i=>i.completed).length} 项已完成</p></div>{currentList&&currentList.name!=='Inbox'&&<div className="list-actions"><button className="icon" title="重命名清单" onClick={renameList}><MoreHorizontal/></button><button className="icon danger" title="删除清单" onClick={()=>setDeleteTarget(currentList)}><Trash2/></button></div>}</div>
     <QuickAdd onAdd={quickAdd}/>
     {loading?<Empty text="正在读取本地数据…"/>:visible.length===0?<Empty text={search?'没有匹配的项目':'这里很安静。添加一个项目，或者从任意文本导入。'}/>:<ItemGroups items={visible} allItems={items} lists={lists} view={view} toggle={toggle} edit={setEditor} remove={removeItem}/>} 
    </>}
   </div></section>
  </main>
  {editor&&<ItemEditor item={editor} lists={lists} close={()=>setEditor(null)} saved={()=>{setEditor(null);notify(editor.id?'任务已保存':'任务已创建');load()}}/>}
  {deleteTarget&&<ConfirmDialog title="删除这个清单？" description={`“${deleteTarget.name}”中的 ${deleteTarget.item_count} 个任务将一起删除，且无法恢复。`} confirmLabel="删除清单" busy={deleting} onCancel={()=>!deleting&&setDeleteTarget(null)} onConfirm={deleteList}/>} 
  {toast&&<div className={`toast ${toast.kind}`} role="status"><span>{toast.kind==='success'?<Check/>:<X/>}</span><p>{toast.message}</p><button onClick={()=>setToast(null)} aria-label="关闭提示"><X/></button></div>}
 </div>
}

function Sidebar({open,close,view,setView,lists,addList}:{open:boolean;close:()=>void;view:View;setView:(v:View)=>void;lists:List[];addList:()=>void}){
 const nav:[View,React.ReactNode,string,number?][]=[['inbox',<Inbox/>,'Inbox',lists.find(x=>x.name==='Inbox')?.pending_count],['today',<CalendarDays/>,'今天'],['upcoming',<Clock3/>,'即将到来'],['all',<LayoutList/>,'全部']]
 const resizeTo=(width:number)=>{const next=Math.max(220,Math.min(420,Math.round(width)));document.documentElement.style.setProperty('--sidebar-width',`${next}px`);localStorage.sidebarWidth=String(next);return next}
 const persistWidth=(width:number)=>{const next=resizeTo(width);void api.put('/api/settings/ui',{sidebar_width:next}).catch(()=>{})}
 useEffect(()=>{const saved=Number(localStorage.sidebarWidth);if(Number.isFinite(saved)&&saved>0)resizeTo(saved);api.get<{sidebar_width:number}>('/api/settings/ui').then(settings=>resizeTo(settings.sidebar_width)).catch(()=>{})},[])
 const currentWidth=()=>Number.parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--sidebar-width'))||256
 const startResize=(event:React.PointerEvent<HTMLDivElement>)=>{if(window.innerWidth<=760)return;event.preventDefault();const startX=event.clientX,startWidth=currentWidth();document.body.classList.add('sidebar-resizing');const move=(moveEvent:PointerEvent)=>resizeTo(startWidth+moveEvent.clientX-startX);const stop=()=>{persistWidth(currentWidth());document.body.classList.remove('sidebar-resizing');window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',stop);window.removeEventListener('pointercancel',stop)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',stop);window.addEventListener('pointercancel',stop)}
 const keyResize=(event:React.KeyboardEvent<HTMLDivElement>)=>{if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();persistWidth(currentWidth()+(event.key==='ArrowRight'?12:-12))}}
 return <><aside className={`sidebar ${open?'open':''}`}><div className="brand"><span className="brandmark"><Check/></span><span>Checklist</span><button className="icon mobile" onClick={close}><X/></button></div><nav>{nav.map(([id,icon,label,count])=><button key={id} className={view===id?'active':''} onClick={()=>setView(id)}>{icon}<span>{label}</span>{count!==undefined&&<em>{count}</em>}</button>)}</nav><div className="section-head"><span>我的清单</span><button onClick={addList}><Plus/></button></div><nav className="list-nav">{lists.filter(x=>x.name!=='Inbox').map((l,i)=><button key={l.id} title={l.name} className={view===`list-${l.id}`?'active':''} onClick={()=>setView(`list-${l.id}`)}><i style={{background:l.color||colors[i%colors.length]}}/><span>{l.name}</span><em>{l.pending_count}</em></button>)}</nav><div className="sidebar-bottom"><nav><button className={view==='history'?'active':''} onClick={()=>setView('history')}><History/><span>历史</span></button><button className={view==='import'?'active':''} onClick={()=>setView('import')}><FileUp/><span>导入</span></button><button className={view==='settings'?'active':''} onClick={()=>setView('settings')}><Settings/><span>设置</span></button></nav></div><div className="sidebar-resizer" role="separator" aria-label="调整侧边栏宽度" aria-orientation="vertical" tabIndex={0} onPointerDown={startResize} onKeyDown={keyResize} onDoubleClick={()=>persistWidth(256)} title="拖动调整宽度；双击恢复默认"/></aside>{open&&<div className="scrim" onClick={close}/>}</>
}

function ConfirmDialog({title,description,confirmLabel,busy,onCancel,onConfirm}:{title:string;description:string;confirmLabel:string;busy:boolean;onCancel:()=>void;onConfirm:()=>void|Promise<void>}){
 useEffect(()=>{const close=(event:KeyboardEvent)=>{if(event.key==='Escape'&&!busy)onCancel()};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close)},[busy,onCancel])
 return <div className="modal-wrap confirm-wrap" onMouseDown={event=>event.target===event.currentTarget&&!busy&&onCancel()}><section className="confirm-dialog" role="alertdialog" aria-modal="true" aria-labelledby="confirm-title" aria-describedby="confirm-description"><div className="confirm-icon"><TriangleAlert/></div><div className="confirm-copy"><p className="eyebrow">危险操作</p><h2 id="confirm-title">{title}</h2><p id="confirm-description">{description}</p></div><button type="button" className="icon confirm-close" aria-label="关闭" disabled={busy} onClick={onCancel}><X/></button><div className="confirm-actions"><button type="button" className="secondary" autoFocus disabled={busy} onClick={onCancel}>取消</button><button type="button" className="danger-button" disabled={busy} onClick={onConfirm}>{busy?'正在删除…':confirmLabel}</button></div></section></div>
}

function QuickAdd({onAdd}:{onAdd:(s:string)=>void}){const [value,setValue]=useState('');return <form className="quick" onSubmit={e=>{e.preventDefault();onAdd(value);setValue('')}}><Plus/><input value={value} onChange={e=>setValue(e.target.value)} placeholder="添加一个项目…"/><span>回车保存</span></form>}

function NumericCombo({value,min,max,options,unit,onChange}:{value:number;min:number;max:number;options:number[];unit:string;onChange:(value:number)=>void}){
 const [draft,setDraft]=useState(String(value)),[open,setOpen]=useState(false)
 useEffect(()=>setDraft(String(value)),[value])
 const commit=(raw=draft)=>{const parsed=Number.parseInt(raw,10),next=Math.max(min,Math.min(max,Number.isFinite(parsed)?parsed:min));setDraft(String(next));onChange(next)}
 const update=(raw:string)=>{if(!/^\d*$/.test(raw))return;setDraft(raw);const parsed=Number.parseInt(raw,10);if(Number.isFinite(parsed)&&parsed>=min&&parsed<=max)onChange(parsed)}
 const choose=(next:number)=>{setDraft(String(next));onChange(next);setOpen(false)}
 return <div className={`number-combo ${open?'open':''}`} onBlur={event=>{if(!event.currentTarget.contains(event.relatedTarget as Node)){commit();setOpen(false)}}}>
  <div className="number-combo-control"><input type="text" inputMode="numeric" value={draft} aria-label={`${unit}数`} onFocus={()=>setOpen(true)} onChange={event=>update(event.target.value)} onKeyDown={event=>{if(event.key==='Enter'){event.preventDefault();commit();setOpen(false)}else if(event.key==='Escape')setOpen(false)}}/><span>{unit}</span><button type="button" aria-label={`选择${unit}`} aria-expanded={open} onMouseDown={event=>event.preventDefault()} onClick={()=>setOpen(current=>!current)}><ChevronDown/></button></div>
  {open&&<div className="number-combo-menu">{options.map(option=><button type="button" key={option} className={option===value?'selected':''} onMouseDown={event=>event.preventDefault()} onClick={()=>choose(option)}>{option} {unit}</button>)}</div>}
 </div>
}

function ExcludedDatePicker({dates,minDate,onChange}:{dates:string[];minDate:string;onChange:(dates:string[])=>void}){
 const initial=new Date(`${minDate||isoToday()}T12:00:00`),[month,setMonth]=useState(()=>new Date(initial.getFullYear(),initial.getMonth(),1,12)),[open,setOpen]=useState(false)
 useEffect(()=>{const next=new Date(`${minDate||isoToday()}T12:00:00`);setMonth(new Date(next.getFullYear(),next.getMonth(),1,12))},[minDate])
 const year=month.getFullYear(),monthIndex=month.getMonth(),daysInMonth=new Date(year,monthIndex+1,0,12).getDate(),offset=(new Date(year,monthIndex,1,12).getDay()+6)%7
 const cells=Array.from({length:Math.ceil((offset+daysInMonth)/7)*7},(_,index)=>{const day=index-offset+1;return day>0&&day<=daysInMonth?`${year}-${String(monthIndex+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`:null})
 const selected=new Set(dates),toggle=(value:string)=>onChange(selected.has(value)?dates.filter(date=>date!==value):[...dates,value].sort())
 const moveMonth=(delta:number)=>setMonth(current=>new Date(current.getFullYear(),current.getMonth()+delta,1,12))
 return <div className="date-picker-field"><span className="field-label">排除日期</span><button type="button" className={`calendar-trigger ${open?'active':''}`} onClick={()=>setOpen(value=>!value)}><CalendarDays/><span>{dates.length?`已选择 ${dates.length} 天`:'展开日历选择'}</span><ChevronRight className={open?'rotated':''}/></button>{open&&<div className="calendar-popover"><div className="calendar-heading"><button type="button" className="icon" aria-label="上个月" onClick={()=>moveMonth(-1)}><ChevronLeft/></button><strong>{year} 年 {monthIndex+1} 月</strong><button type="button" className="icon" aria-label="下个月" onClick={()=>moveMonth(1)}><ChevronRight/></button></div><div className="calendar-weekdays">{['一','二','三','四','五','六','日'].map(day=><span key={day}>{day}</span>)}</div><div className="calendar-grid">{cells.map((value,index)=>value?<button type="button" key={value} disabled={value<minDate} className={selected.has(value)?'selected':''} aria-pressed={selected.has(value)} onClick={()=>toggle(value)}>{Number(value.slice(-2))}</button>:<span key={`empty-${index}`}/>)}</div><div className="calendar-actions"><button type="button" className="text-button" disabled={!dates.length} onClick={()=>onChange([])}>清空</button><button type="button" className="secondary" onClick={()=>setOpen(false)}>完成</button></div></div>} {dates.length>0&&<div className="date-chips">{dates.map(date=><button type="button" key={date} title="移除此日期" onClick={()=>toggle(date)}><span>{prettyDate(date)}</span><X/></button>)}</div>}</div>
}

function ItemGroups({items,allItems,lists,view,toggle,edit,remove}:{items:Item[];allItems:Item[];lists:List[];view:View;toggle:(i:Item)=>void;edit:(i:Item)=>void;remove:(id:number)=>void}){
 const container=useRef<HTMLDivElement>(null),positions=useRef(new Map<string,{top:number;left:number}>()),animations=useRef<Animation[]>([])
 const rememberPositions=()=>{const next=new Map<string,{top:number;left:number}>();container.current?.querySelectorAll<HTMLElement>('[data-task-row]').forEach(node=>{const rect=node.getBoundingClientRect();next.set(node.dataset.taskRow!,{top:rect.top,left:rect.left})});positions.current=next}
 const toggleWithMotion=(item:Item)=>{rememberPositions();toggle(item)}
 useLayoutEffect(()=>{
  const nodes=Array.from(container.current?.querySelectorAll<HTMLElement>('[data-task-row]')||[]),previous=positions.current,next=new Map<string,{top:number;left:number}>()
  animations.current.forEach(animation=>animation.cancel());animations.current=[]
  const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches
  nodes.forEach((node,index)=>{const rect=node.getBoundingClientRect(),key=node.dataset.taskRow!,old=previous.get(key);next.set(key,{top:rect.top,left:rect.left});if(!old||reduced)return;const dy=old.top-rect.top,dx=old.left-rect.left;if(Math.abs(dy)<1&&Math.abs(dx)<1)return;const animation=node.animate([{transform:`translate(${dx}px,${dy}px)`},{transform:'translate(0,0)'}],{duration:520,delay:Math.min(index*12,72),easing:'cubic-bezier(.22,1,.36,1)',fill:'both'});animations.current.push(animation);animation.onfinish=()=>animation.cancel()})
  positions.current=next
 },[items,allItems,lists,view])
 useEffect(()=>()=>{animations.current.forEach(animation=>animation.cancel())},[])
 const displayed=useMemo(()=>items.filter(item=>!item.parent_id||!items.some(parent=>parent.id===item.parent_id)),[items])
 const groups=useMemo(()=>{const m=new Map<string,Item[]>();displayed.forEach(i=>{const key=view==='upcoming'?(i.due_date||'未指定'):view==='all'?(lists.find(l=>l.id===i.list_id)?.name||'Inbox'):'项目';m.set(key,[...(m.get(key)||[]),i])});return [...m.entries()].sort(([a],[b])=>a.localeCompare(b))},[displayed,lists,view])
 const renderItem=(item:Item,depth=0):React.ReactNode=>{const children=allItems.filter(child=>child.parent_id===item.id).sort((a,b)=>Number(a.completed)-Number(b.completed)||a.position-b.position);const completedChildren=children.filter(child=>child.completed).length;return <div className={`item-node ${depth?'nested':''}`} key={item.id}><article data-task-row={item.id} className={`item ${item.completed?'done':''}`}><button className="check" aria-label={item.completed?`取消完成：${item.title}`:`完成：${item.title}`} onClick={()=>toggleWithMotion(item)}>{item.completed?<Check/>:<Circle/>}</button><button className="item-body" onClick={()=>edit(item)}><strong>{item.title}</strong>{item.description&&<p className="item-summary">{item.description}</p>}<span>{[children.length&&`${completedChildren}/${children.length} 个子任务`,item.start_date&&`开始 ${prettyDate(item.start_date)}`,item.due_date&&`截止 ${prettyDate(item.due_date)}`,item.estimated_minutes&&`预计 ${formatMinutes(item.estimated_minutes)}`,item.priority&&`优先级 ${item.priority}`,!depth&&lists.find(l=>l.id===item.list_id)?.name].filter(Boolean).join(' · ')}</span></button><button className="icon subtle" onClick={()=>edit(item)} title="编辑任务"><Pencil/></button><button className="icon subtle danger" onClick={()=>remove(item.id)} title="删除"><Trash2/></button><ChevronRight className="chev"/></article>{children.length>0&&<div className="subtask-list">{children.map(child=>renderItem(child,depth+1))}</div>}</div>}
 return <div className="groups" ref={container}>{groups.map(([name,values])=><section className="group" key={name}>{name!=='项目'&&<h2>{view==='upcoming'?prettyDate(name):name}<span>{values.length}</span></h2>}<div className="item-list">{values.map(item=>renderItem(item))}</div></section>)}</div>
}

function ItemEditor({item,close,saved}:{item:Partial<Item>;lists:List[];close:()=>void;saved:()=>void}){
 const [form,setForm]=useState({...item,title:item.title||'',tags:item.tags||[]}),[busy,setBusy]=useState(false),[error,setError]=useState('');const patch=(k:string,v:unknown)=>setForm(x=>({...x,[k]:v}))
 const steps=Array.isArray(form.metadata?.steps)?form.metadata.steps.map(String):[]
 const submit=async(e:React.FormEvent)=>{e.preventDefault();if(!form.title.trim())return;setBusy(true);setError('');try{const data={title:form.title,description:form.description||null,notes:form.notes||null,tags:form.tags||[],metadata:form.metadata||{},...(!item.id?{list_id:item.list_id??null,due_date:item.due_date??null,parent_id:item.parent_id??null}:{})};if(item.id)await api.put(`/api/items/${item.id}`,data);else await api.post('/api/items',data);saved()}catch(reason){setError(String(reason))}finally{setBusy(false)}}
 return <div className="modal-wrap" onMouseDown={e=>e.target===e.currentTarget&&close()}><form className="modal" onSubmit={submit}><div className="modal-head"><div><p className="eyebrow">{item.id?'编辑任务':'新任务'}</p><h2>{item.id?'任务详情':'创建新任务'}</h2>{item.id&&<small className="editor-hint">自动导入和智能规划创建的任务也可以在这里修改。</small>}</div><button type="button" className="icon" onClick={close}><X/></button></div><label>标题<input autoFocus value={form.title} onChange={e=>patch('title',e.target.value)} placeholder="需要完成什么？"/></label><label>标签<input value={(form.tags||[]).join(', ')} onChange={e=>patch('tags',e.target.value.split(',').map(x=>x.trim()).filter(Boolean))} placeholder="工作, 重要"/></label><label>一句说明<textarea value={form.description||''} onChange={e=>patch('description',e.target.value)} rows={2}/></label>{steps.length>0&&<div className="detail-steps"><strong>关键步骤</strong><ol>{steps.map((step,index)=><li key={`${index}-${step}`}>{step}</li>)}</ol></div>}<label>备注<textarea value={form.notes||''} onChange={e=>patch('notes',e.target.value)} rows={2}/></label>{error&&<div className="notice error editor-error">{error}</div>}<div className="actions"><button type="button" className="secondary" onClick={close}>取消</button><button className="primary" disabled={busy}>{busy?'保存中…':'保存修改'}</button></div></form></div>
}

function ImportPage({onDone}:{onDone:(result:ImportResult)=>Promise<void>}){
 const [sourceMode,setSourceMode]=useState<'text'|'files'|'directory'>('text'),[text,setText]=useState(''),[preview,setPreview]=useState<ParsedPlan|null>(null),[actorAnalysis,setActorAnalysis]=useState<ActorAnalysis|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('')
 const [batch,setBatch]=useState<ImportBatch|null>(null),[schedule,setSchedule]=useState<SchedulePreview|null>(null),[selectedDocs,setSelectedDocs]=useState<number[]>([])
 const [uploadProgress,setUploadProgress]=useState<UploadProgress|null>(null),uploadAbort=useRef<AbortController|null>(null),activeUploadBatch=useRef<number|null>(null)
 const [planning,setPlanning]=useState({start_date:isoToday(),schedule_mode:'days' as 'days'|'end_date',day_count:7,end_date:shiftDate(isoToday(),6),include_weekends:true,excluded_dates:[] as string[],daily_available_minutes:120,intensity:'standard',review_ratio:0.1,buffer_ratio:0.05,allow_media_split:true,allow_section_split:true,goal:''})
 const [selected,setSelected]=useState<string[]>([])
 const [selectedActors,setSelectedActors]=useState<string[]>([]),[customActor,setCustomActor]=useState('')
 const emptyItem=():ParsedItem=>({title:'',tags:[],steps:[],subtasks:[],conditional_actions:[],dependencies:[],metadata:{},duplicate:false})
 const analyzeActors=async()=>{if(!text.trim())return;setBusy(true);setError('');try{setActorAnalysis(await api.post<ActorAnalysis>('/api/import/actors',{content:text}));setSelectedActors([]);setCustomActor('')}catch(e){setError(String(e))}finally{setBusy(false)}}
 const parse=async()=>{const roles=[...selectedActors,customActor.trim()].filter(Boolean);if(!text.trim()||roles.length===0)return;setBusy(true);setError('');try{setPreview(await api.post<ParsedPlan>('/api/import/parse',{content:text,source_name:'Manual Import',llm_mode:'force',granularity:'auto',user_context:roles.join('、'),only_user_actions:true}));setSelected([])}catch(e){setError(String(e))}finally{setBusy(false)}}
 const updateItem=(li:number,ii:number,value:string)=>setPreview(p=>p&&({...p,lists:p.lists.map((l,x)=>x===li?{...l,items:l.items.map((i,y)=>y===ii?{...i,title:value}:i)}:l)}))
 const remove=(li:number,ii:number)=>setPreview(p=>p&&({...p,lists:p.lists.map((l,x)=>x===li?{...l,items:l.items.filter((_,y)=>y!==ii)}:l)}))
 const toggleSelected=(key:string)=>setSelected(current=>current.includes(key)?current.filter(x=>x!==key):[...current,key])
 const toggleActor=(name:string)=>setSelectedActors(current=>current.includes(name)?current.filter(x=>x!==name):[...current,name])
 const mergeSelected=(li:number)=>{if(!preview)return;const indices=selected.filter(key=>key.startsWith(`${li}:`)).map(key=>Number(key.split(':')[1])).sort((a,b)=>a-b);if(indices.length<2)return;const taskList=preview.lists[li],chosen=indices.map(index=>taskList.items[index]);const title=prompt('合并后的任务标题',chosen[0].title)?.trim();if(!title)return;const merged:ParsedItem={...chosen[0],title,description:chosen.map(item=>item.description).filter(Boolean).join('\n')||null,steps:Array.from(new Set([...chosen[0].steps,...chosen.slice(1).flatMap(item=>[item.title,...item.steps])])),subtasks:chosen.flatMap(item=>item.subtasks),conditional_actions:chosen.flatMap(item=>item.conditional_actions),dependencies:Array.from(new Set(chosen.flatMap(item=>item.dependencies)))};const removeSet=new Set(indices);const items=taskList.items.flatMap((item,index)=>index===indices[0]?[merged]:removeSet.has(index)?[]:[item]);setPreview({...preview,lists:preview.lists.map((list,index)=>index===li?{...list,items}:list)});setSelected([])}
 const confirm=async(strategy:'skip'|'import_anyway')=>{if(!preview)return;setBusy(true);setError('');let result:ImportResult;try{result=await api.post<ImportResult>('/api/import/confirm',{plan:preview,source_name:'Manual Import',raw_content:text,duplicate_strategy:strategy})}catch(e){setPreview(null);setError(`确认导入失败：${String(e)}`);setBusy(false);return}try{await onDone(result)}finally{setBusy(false)}}
 const uploadFiles=async(files:FileList|null,kind:'files'|'directory')=>{if(!files?.length)return;const items=Array.from(files),totalBytes=items.reduce((sum,file)=>sum+file.size,0),controller=new AbortController();uploadAbort.current=controller;setBusy(true);setError('');setSchedule(null);setUploadProgress({phase:'scanning',fileName:'正在读取文件清单与媒体时长',processedBytes:0,totalBytes,transferredBytes:0,transferBytes:0,filesDone:0,totalFiles:items.length,startedAt:Date.now()});try{const durations:(number|null)[]=Array(items.length).fill(null);let cursor=0,scanned=0;const workers=Array.from({length:Math.min(4,items.length)},async()=>{while(true){const index=cursor++;if(index>=items.length)return;const file=items[index];if(mediaExtensions.has(fileExtension(file.name)))durations[index]=await readMediaDuration(file);scanned++;setUploadProgress(current=>current&&({...current,fileName:`正在检查 ${file.name}`,filesDone:scanned}))}});await Promise.all(workers);if(controller.signal.aborted)throw new DOMException('Aborted','AbortError');const rootName=kind==='directory'?(relativeFilePath(items[0]).split('/')[0]||'导入目录'):(items.length===1?items[0].name:`${items.length} 个文件`),started=await api.post<ImportBatch>('/api/import/uploads',{root_name:rootName,source_kind:kind,files:items.map((file,index)=>({relative_path:relativeFilePath(file),size:file.size,mime_type:file.type,last_modified:file.lastModified,duration_seconds:durations[index]}))});activeUploadBatch.current=started.id;const byPath=new Map(items.map(file=>[relativeFilePath(file),file])),required=started.documents.filter(doc=>doc.metadata?.upload_required===true),transferBytes=required.reduce((sum,doc)=>sum+doc.size,0),metadataBytes=Math.max(0,totalBytes-transferBytes);let transferred=0,done=started.documents.length-required.length;setUploadProgress({phase:'uploading',fileName:required.length?'准备分块传输':'媒体元数据已读取，无需复制原文件',processedBytes:metadataBytes,totalBytes,transferredBytes:0,transferBytes,filesDone:done,totalFiles:items.length,startedAt:Date.now()});for(const doc of required){const file=byPath.get(doc.relative_path);if(!file)throw new Error(`无法匹配待上传文件：${doc.relative_path}`);setUploadProgress(current=>current&&({...current,phase:'uploading',fileName:file.name}));for(let offset=0;offset<file.size;){const blob=file.slice(offset,Math.min(file.size,offset+8*1024*1024));let result:{received:number}|null=null,lastError:unknown;for(let attempt=0;attempt<3&&!result;attempt++){try{result=await api.chunk<{received:number}>(`/api/import/uploads/${started.id}/${doc.id}/chunk?offset=${offset}`,blob,controller.signal)}catch(uploadError){lastError=uploadError;if(controller.signal.aborted)throw uploadError;if(attempt<2)await new Promise(resolve=>window.setTimeout(resolve,500*(attempt+1)))}}if(!result)throw lastError;const sent=result.received-offset;offset=result.received;transferred+=sent;setUploadProgress(current=>current&&({...current,processedBytes:metadataBytes+transferred,transferredBytes:transferred}))}setUploadProgress(current=>current&&({...current,phase:'extracting',fileName:`正在提取 ${file.name}`}));await api.post(`/api/import/uploads/${started.id}/${doc.id}/complete`);done++;setUploadProgress(current=>current&&({...current,filesDone:done}))}const next=await api.post<ImportBatch>(`/api/import/uploads/${started.id}/complete`);activeUploadBatch.current=null;setBatch(next);setSelectedDocs(next.documents.filter(doc=>doc.extraction_status==='ready'||doc.extraction_status==='warning').map(doc=>doc.id));setUploadProgress(null)}catch(e){if(activeUploadBatch.current!==null){void api.delete(`/api/import/batches/${activeUploadBatch.current}`).catch(()=>{});activeUploadBatch.current=null}setError(e instanceof DOMException&&e.name==='AbortError'?'导入已取消':e instanceof Error?e.message:String(e));setUploadProgress(null)}finally{uploadAbort.current=null;setBusy(false)}}
 const createSchedule=async()=>{if(!batch||!selectedDocs.length)return;setBusy(true);setError('');try{setSchedule(await api.post<SchedulePreview>('/api/planning/schedule',{...planning,goal:planning.goal.trim(),batch_id:batch.id,selected_document_ids:selectedDocs}))}catch(e){setError(String(e))}finally{setBusy(false)}}
 const confirmSchedule=async()=>{if(!batch||!schedule)return;setBusy(true);setError('');try{await onDone(await api.post<ImportResult>('/api/planning/confirm',{batch_id:batch.id,schedule,duplicate_strategy:'skip'}))}catch(e){setError(String(e));setBusy(false)}}
 const resetSource=()=>{uploadAbort.current?.abort();if(batch)void api.delete(`/api/import/batches/${batch.id}`).catch(()=>{});setBatch(null);setSchedule(null);setSelectedDocs([]);setUploadProgress(null);setError('')}
 const formatDuration=(seconds:number)=>`${Math.floor(seconds/3600)} 小时 ${Math.round(seconds%3600/60)} 分钟`
 const uploadPercent=uploadProgress&&uploadProgress.totalBytes?Math.min(100,Math.round(uploadProgress.processedBytes/uploadProgress.totalBytes*100)):0,uploadSeconds=uploadProgress?Math.max(1,(Date.now()-uploadProgress.startedAt)/1000):1,uploadSpeed=uploadProgress?uploadProgress.transferredBytes/uploadSeconds:0,remainingSeconds=uploadProgress&&uploadSpeed>0?Math.max(0,(uploadProgress.transferBytes-uploadProgress.transferredBytes)/uploadSpeed):0
 if(schedule)return <div className="import-page schedule-preview"><div className="page-title"><div><p className="eyebrow">智能规划预览 · {schedule.provider}</p><h1>{schedule.title}</h1><p>{schedule.start_date}～{schedule.end_date} · {schedule.day_count} 天 · 共 {formatMinutes(schedule.total_estimated_minutes)} · 日均 {formatMinutes(schedule.average_daily_minutes)}</p></div><button className="secondary" onClick={()=>setSchedule(null)}>修改规划条件</button></div>{schedule.warnings.map((warning,index)=><div className="notice" key={index}>{warning}</div>)}<div className="schedule-days">{schedule.days.map((day,index)=><section className="schedule-day" key={day.date}><div className="schedule-day-head"><span>DAY {index+1}</span><div><strong>{day.date} · {day.title}</strong><small>{formatMinutes(day.estimated_minutes)} / {formatMinutes(day.capacity_minutes)}</small></div><div className={`load-pill ${day.load_ratio>1?'over':''}`}>{Math.round(day.load_ratio*100)}%</div></div><div className="load-track"><i style={{width:`${Math.min(100,day.load_ratio*100)}%`}}/></div>{day.warnings.map((warning,n)=><p className="schedule-warning" key={n}>{warning}</p>)}<div className="schedule-units">{day.units.map(unit=><article key={unit.id}><FileText/><div><strong>{unit.title}</strong><span>{unit.source_path} · {formatMinutes(unit.estimated_minutes)}{unit.page_from?` · 第 ${unit.page_from}～${unit.page_to||unit.page_from} 页`:''}{unit.media_start!==null&&unit.media_start!==undefined?` · ${Math.floor(unit.media_start/60)}:${String(unit.media_start%60).padStart(2,'0')}～${Math.floor((unit.media_end||0)/60)}:${String((unit.media_end||0)%60).padStart(2,'0')}`:''}</span>{unit.summary&&<p>{unit.summary}</p>}</div></article>)}</div></section>)}</div>{error&&<div className="notice error">{error}</div>}<div className="sticky-actions"><button className="secondary" onClick={()=>setSchedule(null)}>返回调整</button><button className="primary" disabled={busy} onClick={confirmSchedule}>{busy?'正在写入…':'确认并创建每日任务'}</button></div></div>
 if(batch)return <div className="import-page batch-preview">
  <div className="page-title"><div><p className="eyebrow">资料清单</p><h1>{batch.root_name}</h1><p>{batch.file_count} 个文件 · 成功 {batch.supported_count} · 跳过 {batch.skipped_count} · 失败 {batch.error_count}{batch.total_media_seconds?` · 媒体 ${formatDuration(batch.total_media_seconds)}`:''}</p></div><button className="secondary" onClick={resetSource}>重新选择</button></div>
  <div className="planning-layout">
   <section className="document-panel"><h2>选择用于规划的资料</h2><div className="document-list">{batch.documents.map(doc=>{const usable=doc.extraction_status==='ready'||doc.extraction_status==='warning',checked=selectedDocs.includes(doc.id);return <label className={`document-row ${usable?'':'disabled'}`} key={doc.id}><input type="checkbox" disabled={!usable} checked={checked} onChange={()=>setSelectedDocs(current=>current.includes(doc.id)?current.filter(id=>id!==doc.id):[...current,doc.id])}/><FileText/><div><strong>{doc.relative_path}</strong><span>{doc.extension.toUpperCase()||'FILE'} · {(doc.size/1024/1024).toFixed(2)} MB{doc.page_count?` · ${doc.page_count} 页`:''}{doc.slide_count?` · ${doc.slide_count} 张`:''}{doc.sheet_count?` · ${doc.sheet_count} 个工作表`:''}{doc.duration_seconds?` · ${formatDuration(doc.duration_seconds)}`:''}</span>{doc.error_message&&<small>{doc.error_message}</small>}</div><em>{doc.extraction_status}</em></label>})}</div></section>
   <section className="planning-panel"><h2>按天规划</h2>
    <label><span className="field-title">任务/学习目标 <em className="optional-mark">选填</em></span><textarea rows={3} value={planning.goal} onChange={e=>setPlanning({...planning,goal:e.target.value})} placeholder="例如：整理会议行动项；或理解核心概念并完成练习"/><small className="field-hint">不填写时，将根据所选资料自动概括目标。</small></label>
    <div className="range-mode-field"><span className="field-label">任务时间范围</span><div className="range-mode-picker"><button type="button" className={planning.schedule_mode==='days'?'selected':''} onClick={()=>setPlanning({...planning,schedule_mode:'days'})}>开始日期 + 天数</button><button type="button" className={planning.schedule_mode==='end_date'?'selected':''} onClick={()=>setPlanning({...planning,schedule_mode:'end_date',end_date:planning.end_date<planning.start_date?planning.start_date:planning.end_date})}>开始日期 + 结束日期</button></div></div>
    <div className="grid2"><label>开始日期<input type="date" value={planning.start_date} onChange={e=>{const start=e.target.value;setPlanning({...planning,start_date:start,end_date:planning.end_date<start?shiftDate(start,Math.max(0,planning.day_count-1)):planning.end_date,excluded_dates:planning.excluded_dates.filter(date=>date>=start)})}}/></label>{planning.schedule_mode==='days'?<label>规划天数<input type="number" min={1} max={365} value={planning.day_count} onChange={e=>{const dayCount=Math.max(1,Math.min(365,Number(e.target.value)||1));setPlanning({...planning,day_count:dayCount,end_date:shiftDate(planning.start_date,dayCount-1)})}}/></label>:<label>结束日期<input type="date" min={planning.start_date} max={shiftDate(planning.start_date,365)} value={planning.end_date} onChange={e=>setPlanning({...planning,end_date:e.target.value,excluded_dates:planning.excluded_dates.filter(date=>date<=e.target.value)})}/></label>}</div>
    <div className="planning-primary-grid"><div className="time-control"><span className="field-label">每日可用时间</span><div className="time-inputs"><NumericCombo value={Math.floor(planning.daily_available_minutes/60)} min={0} max={24} options={[0,1,2,3,4,5,6,8,10,12,24]} unit="小时" onChange={hours=>setPlanning({...planning,daily_available_minutes:Math.min(1440,hours*60+planning.daily_available_minutes%60)})}/><NumericCombo value={planning.daily_available_minutes%60} min={0} max={59} options={[0,10,15,20,30,45]} unit="分钟" onChange={minutes=>setPlanning({...planning,daily_available_minutes:Math.min(1440,Math.floor(planning.daily_available_minutes/60)*60+minutes)})}/></div>{planning.daily_available_minutes<15&&<small className="field-error">每日可用时间至少为 15 分钟</small>}</div><label className="intensity-field">学习强度<select value={planning.intensity} onChange={e=>setPlanning({...planning,intensity:e.target.value})}><option value="light">轻量理解</option><option value="standard">标准学习</option><option value="intensive">深入学习</option></select></label></div>
    <ExcludedDatePicker dates={planning.excluded_dates} minDate={planning.start_date} onChange={dates=>setPlanning({...planning,excluded_dates:dates})}/>
    <div className="grid2"><label>复习比例<input type="number" min={0} max={0.5} step={0.05} value={planning.review_ratio} onChange={e=>setPlanning({...planning,review_ratio:Math.max(0,Math.min(.5,Number(e.target.value)||0))})}/></label><label>缓冲比例<input type="number" min={0} max={0.5} step={0.05} value={planning.buffer_ratio} onChange={e=>setPlanning({...planning,buffer_ratio:Math.max(0,Math.min(.5,Number(e.target.value)||0))})}/></label></div>
    <label className="switch"><input type="checkbox" checked={planning.include_weekends} onChange={e=>setPlanning({...planning,include_weekends:e.target.checked})}/>周末也安排任务</label><label className="switch"><input type="checkbox" checked={planning.allow_media_split} onChange={e=>setPlanning({...planning,allow_media_split:e.target.checked})}/>允许按连续时间段拆分长视频/音频</label><label className="switch"><input type="checkbox" checked={planning.allow_section_split} onChange={e=>setPlanning({...planning,allow_section_split:e.target.checked})}/>允许在自然边界拆分长文档</label>
    <button className="primary wide" disabled={busy||!selectedDocs.length||planning.daily_available_minutes<15} onClick={createSchedule}>{busy?'正在分析与排程…':'生成每日计划'}</button>{error&&<div className="notice error">{error}</div>}
   </section>
  </div>
 </div>
 if(preview){const taskCount=preview.lists.reduce((n,l)=>n+l.items.length,0),stepCount=preview.lists.reduce((n,l)=>n+l.items.reduce((m,i)=>m+i.steps.length+i.subtasks.length,0),0);return <div className="import-page"><div className="page-title"><div><p className="eyebrow">解析预览 · {preview.parser}</p><input className="title-input" value={preview.title} onChange={e=>setPreview({...preview,title:e.target.value})}/><p>{taskCount} 个顶层任务 · {stepCount} 个步骤/子任务 · {preview.granularity==='auto'?'AI 自动判断粒度':preview.granularity}</p></div><button className="secondary" onClick={()=>setPreview(null)}>返回选择主体</button></div>{preview.goal&&<div className="agent-report"><strong>目标</strong><span>{preview.goal}</span><small>{preview.provider&&`${preview.provider} · `}{preview.model||'本地规则'} · {preview.confidence.toFixed(2)}</small></div>}{preview.warnings.map((warning,index)=><div className="notice" key={index}>{warning}</div>)}{preview.duplicate_count>0&&<div className="notice">发现 {preview.duplicate_count} 个潜在重复项目。确认时可跳过它们。</div>}<div className="preview-lists">{preview.lists.map((l,li)=>{const selectedCount=selected.filter(key=>key.startsWith(`${li}:`)).length;return <section key={li} className="preview-list"><div className="preview-list-head"><input value={l.name} onChange={e=>setPreview({...preview,lists:preview.lists.map((x,n)=>n===li?{...x,name:e.target.value}:x)})}/>{selectedCount>=2&&<button className="secondary" onClick={()=>mergeSelected(li)}>合并选中的 {selectedCount} 项</button>}</div>{l.items.map((i,ii)=><div key={ii} className={i.duplicate?'preview-task duplicate':'preview-task'}><div className="preview-item"><input type="checkbox" checked={selected.includes(`${li}:${ii}`)} onChange={()=>toggleSelected(`${li}:${ii}`)}/><input value={i.title} onChange={e=>updateItem(li,ii,e.target.value)}/>{i.duplicate&&<small>重复</small>}<button onClick={()=>remove(li,ii)}><X/></button></div>{Boolean(i.description||i.steps.length||i.subtasks.length||i.conditional_actions.length||i.dependencies.length)&&<div className="task-detail">{i.description&&<p>{i.description}</p>}{i.steps.length>0&&<div><strong>执行步骤</strong><ul>{i.steps.map((step,n)=><li key={n}>{step}</li>)}</ul></div>}{i.subtasks.length>0&&<div><strong>子任务</strong><ul>{i.subtasks.map((child,n)=><li key={n}>{child.title}</li>)}</ul></div>}{i.conditional_actions.length>0&&<div><strong>条件处理</strong><ul>{i.conditional_actions.map((action,n)=><li key={n}>{String(action.condition||'满足条件时')}：{Array.isArray(action.actions)?action.actions.join('、'):String(action.actions||'')}</li>)}</ul></div>}{i.dependencies.length>0&&<small>依赖：{i.dependencies.join('、')}</small>}</div>}</div>)}<button className="add-row" onClick={()=>setPreview({...preview,lists:preview.lists.map((x,n)=>n===li?{...x,items:[...x.items,emptyItem()]}:x)})}><Plus/>添加任务</button></section>})}</div><div className="sticky-actions">{preview.duplicate_count>0&&<button className="secondary" onClick={()=>confirm('import_anyway')}>仍然全部导入</button>}<button className="primary" onClick={()=>confirm('skip')} disabled={busy}>确认导入</button></div></div>}
 if(actorAnalysis){const roleCount=selectedActors.length+(customActor.trim()?1:0);return <div className="import-page actor-stage"><div className="page-title"><div><p className="eyebrow">第 2 步 · 选择责任主体</p><h1>这份内容涉及谁？</h1><p>{actorAnalysis.summary||`Agent 识别出 ${actorAnalysis.actors.length} 个责任主体。请选择你要导入的身份。`}</p></div><button className="secondary" onClick={()=>{setActorAnalysis(null);setSelectedActors([]);setCustomActor('')}}>返回原文</button></div><div className="actor-meta"><span>{actorAnalysis.provider&&`${actorAnalysis.provider} · `}{actorAnalysis.model||'Agent'}</span><span>可多选</span></div>{actorAnalysis.warnings.map((warning,index)=><div className="notice" key={index}>{warning}</div>)}<div className="actor-grid">{actorAnalysis.actors.map(actor=>{const active=selectedActors.includes(actor.name);return <button type="button" key={actor.name} className={`actor-card ${active?'selected':''}`} aria-pressed={active} onClick={()=>toggleActor(actor.name)}><span className="actor-check">{active?<Check/>:<Circle/>}</span><span className="actor-card-copy"><strong>{actor.name}{actor.is_general&&<em>通用</em>}</strong><small>{actor.description||'原文中的责任主体'}</small>{actor.evidence.length>0&&<q>{actor.evidence[0]}</q>}</span><span className="actor-estimate">约 {actor.estimated_task_count} 项</span></button>})}</div><label className="actor-custom"><strong>没有合适的主体？</strong><input value={customActor} onChange={e=>setCustomActor(e.target.value)} placeholder="输入自定义身份，例如：普通团员（非团支书）"/><small>自定义身份会与已选主体一起交给 Agent 进行责任过滤。</small></label>{error&&<div className="notice error"><strong>解析失败：</strong>{error}</div>}<div className="actor-stage-actions"><span>{roleCount?`已选择 ${roleCount} 个主体`:'请至少选择一个主体'}</span><button className="primary" disabled={busy||roleCount===0} onClick={parse}>{busy?'正在生成任务…':'按所选主体生成任务'}<ChevronRight/></button></div><div className="flow"><span>已识别主体</span><ChevronRight/><span className="flow-active">选择身份</span><ChevronRight/><span>生成任务</span><ChevronRight/><span>确认保存</span></div></div>}
 return <div className="import-page">
  <div className="page-title"><div><p className="eyebrow">导入与智能规划</p><h1>导入内容</h1><p>支持粘贴文本、多文件或整个目录，并自动整理为任务或按天计划。</p></div></div>
  <div className="source-picker"><button disabled={busy} className={sourceMode==='text'?'selected':''} onClick={()=>setSourceMode('text')}><Command/><strong>粘贴文本</strong><span>分析通知或大任务</span></button><label className={`${sourceMode==='files'?'selected':''} ${busy?'busy':''}`} onClick={()=>!busy&&setSourceMode('files')}><FileUp/><strong>选择文件</strong><span>支持多种文档与媒体</span><input disabled={busy} type="file" multiple accept=".txt,.md,.markdown,.json,.csv,.tsv,.html,.htm,.log,.pdf,.docx,.pptx,.xlsx,.srt,.vtt,.mp4,.mkv,.mov,.webm,.m4v,.mp3,.m4a,.wav,.flac,.aac,.ogg" onChange={e=>uploadFiles(e.target.files,'files')}/></label><label className={`${sourceMode==='directory'?'selected':''} ${busy?'busy':''}`} onClick={()=>!busy&&setSourceMode('directory')}><FolderOpen/><strong>选择目录</strong><span>递归读取目录资料</span><input disabled={busy} type="file" multiple {...({webkitdirectory:''} as Record<string,string>)} onChange={e=>uploadFiles(e.target.files,'directory')}/></label></div>
  {sourceMode!=='text'?uploadProgress?<section className="upload-progress" aria-live="polite"><div className="upload-progress-head"><div><span>{uploadProgress.phase==='scanning'?'分析文件':uploadProgress.phase==='uploading'?'分块传输':'提取内容'}</span><strong>{uploadPercent}%</strong></div><button type="button" className="secondary" disabled={uploadProgress.phase==='extracting'} onClick={()=>uploadAbort.current?.abort()}>{uploadProgress.phase==='extracting'?<><RefreshCw/>正在处理</>:<><X/>取消</>}</button></div><div className="upload-progress-track"><i style={{width:`${uploadPercent}%`}}/></div><h3 title={uploadProgress.fileName}>{uploadProgress.fileName}</h3><div className="upload-progress-stats"><span>{formatBytes(uploadProgress.processedBytes)} / {formatBytes(uploadProgress.totalBytes)}</span><span>{uploadProgress.filesDone} / {uploadProgress.totalFiles} 个文件</span>{uploadProgress.phase==='uploading'&&uploadProgress.transferredBytes>0&&<span>{formatBytes(uploadSpeed)}/秒{remainingSeconds>1?` · 约剩 ${formatMinutes(Math.ceil(remainingSeconds/60))}`:''}</span>}</div><p>音视频可读取到时长时只建立本地索引，不复制原始大文件；文档按 8 MB 分块处理，应用可持续响应。</p>{error&&<div className="notice error">{error}</div>}</section>:<div className="drop-hint"><FolderOpen/><h3>{sourceMode==='directory'?'选择一个资料目录':'选择一个或多个文件'}</h3><p>支持 TXT、Markdown、JSON、CSV、HTML、PDF、DOCX、PPTX、XLSX、字幕以及常见音视频格式。大型资料会自动分块处理并显示进度。</p>{error&&<div className="notice error">{error}</div>}</div>:<>
  <section className="agent-options"><strong>AI 自动判断任务粒度</strong><p>模型根据具体内容决定任务数量、层级和子任务，无需预先选择粒度或任务上限。生成后可以在预览中修改。</p></section>
  <div className="import-box"><textarea value={text} onChange={e=>{setText(e.target.value);setActorAnalysis(null);setPreview(null);setError('')}} placeholder={'例如：\n下周完成新版本发布。上线前跑测试并备份数据库；发布后观察日志，如果出现严重错误就回滚并通知负责人。'}/><div className="import-footer"><span><Command/>先识别主体，再精确生成任务</span><button className="primary" disabled={busy||!text.trim()} onClick={analyzeActors}>{busy?'正在识别…':'识别责任主体'}<ChevronRight/></button></div></div>
  {error&&<div className="notice error"><strong>识别失败：</strong>{error}</div>}<div className="flow"><span className="flow-active">识别主体</span><ChevronRight/><span>选择身份</span><ChevronRight/><span>生成任务</span><ChevronRight/><span>确认保存</span></div></>}
 </div>
}

type Provider={id:number;name:string;base_url:string;model:string;api_key_env:string;enabled:boolean;has_api_key:boolean}
type GmailStatus={authorization_required?:boolean;client_configured:boolean;connected:boolean;email?:string|null;history_id?:string|null;last_synced_at?:string|null;last_sync_error?:string|null;sync_interval_hours:number;lookback_days:number;auto_import:boolean;auto_import_threshold:number;exclude_promotions:boolean;candidate_count:number;processed_count:number}
type GmailCandidate={id:number;subject:string;sender:string;received_at?:string|null;status:string;classification?:string|null;confidence?:number|null;reason?:string|null;preview_title?:string|null;body_excerpt?:string|null;created_at:string}

function ProviderRow({provider,reload,notify}:{provider:Provider;reload:()=>Promise<void>;notify:(message:string,kind?:'success'|'error')=>void}){
 const [key,setKey]=useState(''),[busy,setBusy]=useState(false),[message,setMessage]=useState(''),[confirming,setConfirming]=useState(false)
 const update=async(data:unknown)=>{setBusy(true);setMessage('');try{await api.put(`/api/settings/providers/${provider.id}`,data);setKey('');setMessage('已保存');notify(`${provider.name} 配置已保存`);await reload()}catch(e){setMessage(String(e));notify(String(e),'error')}finally{setBusy(false)}}
 const test=async()=>{setBusy(true);setMessage('');try{const result=await api.post<{message:string}>(`/api/settings/providers/${provider.id}/test`);setMessage(result.message);notify(`${provider.name} 连接成功`)}catch(e){setMessage(String(e));notify(String(e),'error')}finally{setBusy(false)}}
 const remove=async()=>{setBusy(true);try{await api.delete(`/api/settings/providers/${provider.id}`);setConfirming(false);notify(`${provider.name} 已删除`);await reload()}catch(e){notify(`删除失败：${String(e)}`,'error')}finally{setBusy(false)}}
 return <><div className="provider"><span className="status" data-on={provider.enabled}/><div className="provider-info"><div><strong>{provider.name}</strong><span className={provider.has_api_key?'key-state ready':'key-state'}>{provider.has_api_key?'密钥已配置':'未配置密钥'}</span></div><small>{provider.model} · {provider.base_url}</small><div className="provider-key"><input type="password" autoComplete="new-password" value={key} onChange={e=>setKey(e.target.value)} placeholder={provider.has_api_key?'输入新 Key 可替换现有密钥':'输入 API Key'}/><button className="secondary" disabled={busy||!key.trim()} onClick={()=>update({api_key:key})}>保存 Key</button><button className="secondary" disabled={busy||!provider.has_api_key} onClick={test}>测试连接</button><label className="switch"><input type="checkbox" checked={provider.enabled} disabled={busy} onChange={e=>update({enabled:e.target.checked})}/>启用</label><button className="icon danger" title="删除 Provider" onClick={()=>setConfirming(true)}><Trash2/></button></div>{message&&<small className={message==='连接成功'||message==='已保存'?'form-message success':'form-message'}>{message}</small>}</div></div>{confirming&&<ConfirmDialog title="删除这个模型服务？" description={`“${provider.name}”的配置和本机保存的 API Key 将一起删除，且无法恢复。`} confirmLabel="删除服务" busy={busy} onCancel={()=>!busy&&setConfirming(false)} onConfirm={remove}/>}</>
}

function SettingsPage({theme,setTheme,notify,onTasksChanged}:{theme:string;setTheme:(s:string)=>void;notify:(message:string,kind?:'success'|'error')=>void;onTasksChanged:()=>Promise<void>}){
 const [providers,setProviders]=useState<Provider[]>([]),[form,setForm]=useState({name:'DeepSeek',base_url:'https://api.deepseek.com',model:'deepseek-flash',api_key_env:'DEEPSEEK_API_KEY',api_key:'',enabled:true}),[message,setMessage]=useState(''),[busy,setBusy]=useState(false)
 const [gmail,setGmail]=useState<GmailStatus|null>(null),[gmailCandidates,setGmailCandidates]=useState<GmailCandidate[]>([]),[gmailBusy,setGmailBusy]=useState(false),[editGmailClient,setEditGmailClient]=useState(false),[gmailClient,setGmailClient]=useState({client_id:'',client_secret:''})
 const reload=async()=>setProviders(await api.get<Provider[]>('/api/settings/providers'))
 const reloadGmail=async()=>{const [status,candidates]=await Promise.all([api.get<GmailStatus>('/api/integrations/gmail/status'),api.get<GmailCandidate[]>('/api/integrations/gmail/candidates')]);setGmail(status);setGmailCandidates(candidates)}
 useEffect(()=>{reload();reloadGmail();const connected=(event:MessageEvent)=>{if(event.data?.type==='gmail-connected')reloadGmail()};window.addEventListener('message',connected);return()=>window.removeEventListener('message',connected)},[])
 const save=async()=>{const normalized={...form,name:form.name.trim(),base_url:form.base_url.trim(),model:form.model.trim(),api_key_env:form.api_key_env.trim(),api_key:form.api_key.trim()},duplicate=providers.find(provider=>provider.name.trim().toLocaleLowerCase()===normalized.name.toLocaleLowerCase());if(duplicate){const warning=`已存在名为“${duplicate.name}”的 Provider，请直接在上方保存 Key 或修改配置`;setMessage(warning);notify(warning,'error');return}setBusy(true);setMessage('');try{await api.post('/api/settings/providers',normalized);setForm({name:'',base_url:'',model:'',api_key_env:'',api_key:'',enabled:true});setMessage('Provider 已添加，API Key 已在本机加密保存');notify(`${normalized.name} 已添加`);await reload()}catch(e){const detail=e instanceof Error?e.message:String(e);setMessage(detail);notify(detail,'error')}finally{setBusy(false)}}
 const saveGmailClient=async()=>{setGmailBusy(true);try{await api.post('/api/integrations/gmail/client',gmailClient);setGmailClient({client_id:'',client_secret:''});setEditGmailClient(false);notify('Google OAuth 客户端已在本机加密保存');await reloadGmail()}catch(e){notify(String(e),'error')}finally{setGmailBusy(false)}}
 const connectGmail=async()=>{setGmailBusy(true);try{const result=await api.post<{authorization_url:string}>('/api/integrations/gmail/oauth/start');window.open(result.authorization_url,'gmail-oauth','width=720,height=780');notify('请在打开的 Google 页面完成只读授权')}catch(e){notify(String(e),'error')}finally{setGmailBusy(false)}}
 const syncGmail=async()=>{setGmailBusy(true);try{const result=await api.post<{scanned:number;already_processed:number;imported:number;candidates:number;ignored:number}>('/api/integrations/gmail/sync');notify(`同步完成：新扫描 ${result.scanned}，导入 ${result.imported}，候选 ${result.candidates}，已跳过 ${result.already_processed}`);await Promise.all([reloadGmail(),result.imported?onTasksChanged():Promise.resolve()])}catch(e){notify(String(e),'error');await reloadGmail()}finally{setGmailBusy(false)}}
 const saveGmailSettings=async()=>{if(!gmail)return;setGmailBusy(true);try{await api.put('/api/integrations/gmail/settings',{sync_interval_hours:gmail.sync_interval_hours,lookback_days:gmail.lookback_days,auto_import:gmail.auto_import,auto_import_threshold:gmail.auto_import_threshold,exclude_promotions:gmail.exclude_promotions});notify('Gmail 同步设置已保存');await reloadGmail()}catch(e){notify(String(e),'error')}finally{setGmailBusy(false)}}
 const handleCandidate=async(id:number,action:'accept'|'ignore')=>{setGmailBusy(true);try{const result=await api.post<{created?:number}>(`/api/integrations/gmail/candidates/${id}/${action}`);notify(action==='accept'?(result.created?'已通过大模型处理并加入任务列表':'未发现需要新增的任务'):'已忽略该邮件');await Promise.all([reloadGmail(),action==='accept'?onTasksChanged():Promise.resolve()])}catch(e){notify(String(e),'error');await reloadGmail()}finally{setGmailBusy(false)}}
 return <div><div className="page-title"><div><p className="eyebrow">偏好与集成</p><h1>设置</h1><p>连接 Gmail，并配置本机模型服务和界面偏好。</p></div></div><section className="settings-card"><h2>外观</h2><div className="theme-picker">{[['light',<Sun/>,'浅色'],['dark',<Moon/>,'深色'],['system',<Settings/>,'跟随系统']].map(([id,icon,label])=><button key={String(id)} className={theme===id?'selected':''} onClick={()=>{setTheme(String(id));notify(`已切换为${label}主题`)}}>{icon}{label}</button>)}</div></section>
 <section className="settings-card gmail-card"><div className="gmail-heading"><div><h2><Mail/>Gmail 任务同步</h2></div><span className={`integration-state ${gmail?.connected?'connected':''}`}>{gmail?.connected?`已连接 ${gmail.email||''}`:gmail?.authorization_required?'授权已失效，请重新连接':'未连接'}</span></div>
 <p>邮件任务由已启用的大模型理解、拆解后入库；相关邮件正文会发送给该模型服务。验证码和明显广告先在本机过滤。</p>
 {(!gmail?.client_configured||editGmailClient)&&<div className="gmail-client-form"><label>Google OAuth Client ID<input value={gmailClient.client_id} onChange={e=>setGmailClient({...gmailClient,client_id:e.target.value})} placeholder="…apps.googleusercontent.com"/></label><label>Client Secret<input type="password" autoComplete="new-password" value={gmailClient.client_secret} onChange={e=>setGmailClient({...gmailClient,client_secret:e.target.value})}/></label><button className="primary" disabled={gmailBusy||!gmailClient.client_id.trim()||!gmailClient.client_secret.trim()} onClick={saveGmailClient}>保存 OAuth 客户端</button></div>}
 {gmail?.client_configured&&!gmail.connected&&<div className="gmail-connect"><button className="primary" disabled={gmailBusy} onClick={connectGmail}><ShieldCheck/>{gmail.authorization_required?'重新连接 Gmail（只读）':'连接 Gmail（只读）'}</button><button className="secondary" disabled={gmailBusy} onClick={reloadGmail}><RefreshCw/>刷新连接状态</button><button className="secondary" disabled={gmailBusy} onClick={()=>setEditGmailClient(value=>!value)}>更换 OAuth 客户端</button></div>}
 {!gmail?.connected&&gmail&&<p>已登记 {gmail.processed_count} 封 · 候选 {gmail.candidate_count} 封。重新连接同一账户后继续同步。</p>}{!gmail?.connected&&gmail?.last_sync_error&&<div className="notice error">{gmail.last_sync_error}</div>}
 {gmail?.connected&&<><div className="gmail-toolbar"><button className="primary" disabled={gmailBusy} onClick={syncGmail}><RefreshCw/>{gmailBusy?'同步中…':'立即同步'}</button><button className="secondary" disabled={gmailBusy} onClick={reloadGmail}>刷新状态</button><button className="secondary" disabled={gmailBusy} onClick={connectGmail}>重新连接 Gmail</button><span>{gmail.last_synced_at?`上次同步 ${new Date(gmail.last_synced_at).toLocaleString('zh-CN')}`:'尚未同步'} · 已登记 {gmail.processed_count} 封 · 候选 {gmail.candidate_count} 封</span></div>{gmail.last_sync_error&&<div className="notice error">上次同步失败：{gmail.last_sync_error}</div>}<div className="gmail-settings"><label>扫描间隔（小时）<input type="number" min={1} max={168} step={1} value={gmail.sync_interval_hours} onChange={e=>setGmail({...gmail,sync_interval_hours:Math.max(1,Math.min(168,Number(e.target.value)||1))})}/></label><label>首次回看天数<input type="number" min={1} max={90} value={gmail.lookback_days} onChange={e=>setGmail({...gmail,lookback_days:Number(e.target.value)})}/></label><label>自动导入置信度<input type="number" min={0.7} max={1} step={0.01} value={gmail.auto_import_threshold} onChange={e=>setGmail({...gmail,auto_import_threshold:Number(e.target.value)})}/></label><label className="switch"><input type="checkbox" checked={gmail.auto_import} onChange={e=>setGmail({...gmail,auto_import:e.target.checked})}/>大模型高置信度任务自动入库</label><label className="switch"><input type="checkbox" checked={gmail.exclude_promotions} onChange={e=>setGmail({...gmail,exclude_promotions:e.target.checked})}/>首次扫描排除促销分类</label><button className="secondary" disabled={gmailBusy} onClick={saveGmailSettings}>保存同步设置</button></div>
 {gmailCandidates.length>0&&<div className="gmail-candidates"><h3>待确认的邮件</h3>{gmailCandidates.map(candidate=><article key={candidate.id}><div><strong>{candidate.preview_title||candidate.subject}</strong><small>{candidate.sender}{candidate.received_at&&` · ${new Date(candidate.received_at).toLocaleString('zh-CN')}`}</small><p>{candidate.reason}</p>{candidate.body_excerpt&&<blockquote>{candidate.body_excerpt.slice(0,260)}</blockquote>}</div><div><button className="secondary" disabled={gmailBusy} onClick={()=>handleCandidate(candidate.id,'ignore')}>忽略</button><button className="primary" disabled={gmailBusy} onClick={()=>handleCandidate(candidate.id,'accept')}>AI 处理并转为任务</button></div></article>)}</div>}</>}
 </section><section className="settings-card"><h2>LLM Provider</h2>{providers.map(p=><ProviderRow provider={p} reload={reload} notify={notify} key={p.id}/>)}<div className="provider-form"><label>服务名称<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="例如 DeepSeek"/></label><label>API Base URL<input value={form.base_url} onChange={e=>setForm({...form,base_url:e.target.value})} placeholder="https://api.deepseek.com"/></label><label>模型名称<input value={form.model} onChange={e=>setForm({...form,model:e.target.value})} placeholder="deepseek-flash"/></label><label>API Key<input type="password" autoComplete="new-password" value={form.api_key} onChange={e=>setForm({...form,api_key:e.target.value})} placeholder="sk-…（保存后不会回显）"/></label><label>环境变量（可选）<input value={form.api_key_env} onChange={e=>setForm({...form,api_key_env:e.target.value})} placeholder="DEEPSEEK_API_KEY"/></label><label className="switch"><input type="checkbox" checked={form.enabled} onChange={e=>setForm({...form,enabled:e.target.checked})}/>添加后立即启用</label><button className="primary" disabled={busy||!form.name.trim()||!form.base_url.trim()||!form.model.trim()} onClick={save}>{busy?'正在保存…':'添加 Provider'}</button>{message&&<span className={message.startsWith('Provider')?'form-message success':'form-message'}>{message}</span>}</div></section></div>
}

function HistoryPage({plans}:{plans:Plan[]}){return <div><div className="page-title"><div><p className="eyebrow">导入与计划</p><h1>历史</h1><p>保留所有已确认导入的计划。</p></div></div><div className="history-list">{plans.length?plans.map(p=><article key={p.id}><span><Archive/></span><div><strong>{p.title}</strong><p>{p.content_type.replaceAll('_',' ')} · {new Date(p.created_at).toLocaleString('zh-CN')}</p></div></article>):<Empty text="暂无导入历史"/>}</div></div>}
function Empty({text}:{text:string}){return <div className="empty"><span><Check/></span><h3>{text}</h3><p>你的数据保存在本机 SQLite 数据库中。</p></div>}
export default App
